  "share_patch.summary": "{n} {label} {region}-ல் வளர்கிறது.",
  "share_patch.plant_singular": "சேந்தும் செடி",
  "share_patch.plant_plural": "சேந்தும் செடிகள்",
  "share_patch.no_region": "இந்த patch-இன் மண்டலத்தை முதலில் அமைக்கவும் — பொதுவான முன்னணி ஒருமுறை இல்லாமல் அர்த்தமில்லாது இருக்கும்.",
  "share_patch.create_cta": "என் பொதுவான இணைப்பை உருவாக்கவும்",
  "share_patch.creating": "இணைப்பை உருவாக்குகிறது…",
