  "share_patch.copy": "பகிருங்கள்",
  "share_patch.copied": "பக்கேற்பட்டது",
  "share_patch.open": "முன்னோட்டத்தை திற",
  "share_patch.native": "பகிர்க",
  "share_patch.refresh": "எனது அறใหม่ தாவரங்களுடன் புதுப்பிக்கவும்",
  "share_patch.fine_print": "இந்த இணைப்புடன் யாரும் உங்கள் பாட்டையினை, பகுதியில் மற்றும் தாவர பட்டியலை பார்க்கலாம். உங்கள் மின்னஞ்சல், உள்நுழைவு அல்லது உங்கள் தெரு தெளிவான இடம் பகிரப்படவில்லை.",
  "share_patch.delete": "பொது இணைப்பை அகற்று",
  "share_patch.delete_confirm": "நீங்கள் உறுதியாக இருக்கிறீர்களா? URL உடனடியாக செயலிழக்கிறது.",
  "share_patch.delete_yes": "ஆம், அதை அகற்றுங்கள்",
  "share_patch.cancel": "முகாமை",
  "share_patch.close": "மூடு",
  "share_patch.error_generic": "சேவையகம் உடனான உரையாடல் முடியவில்லை — சில क्षणங்களில் மீண்டும் முயற்சிக்கவும்.",
  "share_patch.native_title": "{name} — எனது Patch & Pot தோட்டம்",
  "share_patch.native_body": "நான் வளர்க்கும் {name} இடத்தில் உள்ளதைப் பார்க்கவும்.",
  "share_view.eyebrow": "Patch & Pot இல் பகிர்ந்த மையம்",
  "share_view.loading": "இந்த மையத்தைத் திறக்கிறது…",
