  "grow.situation.windowsill.label": "சீனோரு சலை",
  "grow.situation.windowsill.blurb": "ஒளி நிறைந்த உள்ளக மலர், சிறிய குழாய், வெளியில் செல்ல முடியாது — பாரம்பரிய சமையல் சலை.",
  "grow.situation.workplace.label": "வேலைப்பேசி மேஜை",
  "grow.situation.workplace.blurb": "காரியாலயக் கோணம், நிதானமான ஒளி, வார இறுதிகள் விட்டு செல்லும் போது மன்னிக்கும்.",
  "grow.situation.balcony.label": "குதிரை",
  "grow.situation.balcony.blurb": "ஒரு சமச்சீரான வெளிப்புறக் கொஞ்சம் பாத்திரங்கள் — சில சூரியன், சில காற்று.",
  "grow.situation.rooftop.label": "மேலகம்",
  "grow.situation.rooftop.blurb": "முழு சூரியன், கோடை மாதங்களில் சூடாக, காற்றால் தாக்கப்படுகிறது — கடுமையான, வரைவாய் சகிக்கும் செடிகளைத் தேர்வுசெய்க.",
  "grow.situation.shady-corner.label": "இடம் மூடப்பட்டது",
  "grow.situation.shady-corner.blurb": "ம NORTH-ஏ நோக்கி உள்ள பச்சை, ஒரு மரத்தின் கீழ் அல்லது கட்டிடத்தின் கன்று.",
  "grow.situation.hanging-basket.label": "ஊர்வலம் கூண்டு",
  "grow.situation.hanging-basket.blurb": "மேலே தொங்கும் விளங்கும் செடிகள் — வெளிச்சம், விரைவில் உலர்கிறது, மென்மையான தொடு வேண்டும்.",
  "grow.situation.wall-crevice.label": "சுவர் அடிமண்டலம்",
  "grow.situation.wall-crevice.blurb": "ஒரு கல் உலர்ந்த ச pockets ப pocket அம்மா அல்லது முற்றிலும் உருப்பெறும் கட்செடிய — சிறிய வேர்க்குன்று, பெரிய உலர்ச்சி.",
  "grow.situation.vertical-wall.label": "உயர்ந்த சுவரின் போக்",
  "grow.situation.vertical-wall.blurb": "ஜீவ காடு போக்குகள் அல்லது அடுக்கு நட்டிகள் — மிகவும் குழுக்களில் மட்டுமே.",
  "grow.situation.grow-bag.label": "வளர்ச்சி பை",
  "grow.situation.grow-bag.blurb": "சில்லான த flexible பை, 20–40 L — பரியைப் பெரிய வேர்களுக்கு இதில் ஏற்றார்.",
  "grow.situation.bucket.label": "மீள்செய்யப்பட்ட கோப்பை",
  "grow.situation.bucket.blurb": "ஒரு மீட்டுக் கொண்ட 10–20 L பை நிர்க்கட்டுக்குழுப் துளிகள் — மிகவும் குறைந்த செலவில் ஒரு சரியான பயனுள்ள கிண்டல்.",
  "grow.situation.crate.label": "மரக்கலம்",
  "grow.situation.crate.blurb": "ஒரு பள்ளமான மது அல்லது காய்கறி கலத்தைப் பிடிக்கிறான் — சாலட் மற்றும் மென்மையான வேருளான மூங்கில் விளைவிக்க சிறந்தது.",
  "grow.situation.raised-bed.label": "உயர்ந்த படி",
  "grow.situation.raised-bed.blurb": "பண்டிகை நிலம் அல்லது மரம் பக்கம் கொண்ட படக்கு — ஆழமான வேர்க்கட்டை, பரந்த வையப்பட்டு தேர்வு.",
  "grow.situation.water-jar.label": "நீர் ஜார்கள்",
  "grow.situation.water-jar.blurb": "செல்வாக்கு இல்லாத ஜாம் ஜாரில் உள்ள நீர் — மண்ணோ இல்லை. சமையலறை குப்பைகளை பயன்படுத்தி மறுபடியும் வளர்த்து.",
  "grow.empty": "மேற்கண்ட இடத்திற்கு எந்த தாவரங்களும் பொருந்தவில்லை.",
  "grow.explore_all": "தாவர நூலகத்தை ஆராயுங்கள்",
  "grow.cta.title": "எங்கு வேண்டுமோப் புகாரளிக்கவும்",
  "grow.cta.blurb": "சோடக்கமில்லை? ஒரு சூரிய ஒளியுள்ள திரை, ஒரு சுவரொட்டு அல்லது காய்ந்த buckets போதும். நீங்கள் உண்மையில் உள்ள இடத்தில் வளரும் தாவரங்களை கண்டுபிடிக்கவும்.",
  "grow.cta.button": "உங்கள் இடத்திற்கு தாவரங்களை கண்டுபிடிக்கவும்",
  "recipe.eyebrow": "வாங்குவதற்கான கருத்து",
  "recipe.title": "சமையல் விளக்கங்கள்",
  "recipe.intro": "இங்கு உள்ள ஒவ்வொரு சமையல் முறையும் நீங்கள் வீட்டில் உண்மையான முறையில் வளர்க்கக்கூடிய எதாவது பயன்படுத்துகிறது — வர்க்கத்திற்கு ஏற்ப சமையல், ஒரு பாத்திரத்தில் சமையல் மற்றும் கோடை காலத்தை குளிர்க்காலத்திற்கு கொண்டுவரும் கிமுகங்கள். தற்போது பருவத்தில் உள்ளதை அல்லது நீங்கள் ஏற்கனவே வளர்க்கும்தை அடிப்படையாக வைத்து வடிகட்டவும்.",
